// Dev-only helper behind the "在 VSCode 中编辑此页" button. Builds a
// vscode://file/<abs>:<line> deep link; VSCode reuses the window that already
// has the project folder open and brings it to front (its default behaviour).
// Pure functions only — DOM / heading-in-view logic lives in DocEditButton.
import { slugifyHeading } from './markdown';

// Absolute repo root, injected at dev start via REACT_APP_REPO_ROOT="$PWD" in
// the `start` script. `build` never sets it, so this is '' in production and the
// button (which also checks NODE_ENV) never renders there.
export function getRepoRoot() {
  return process.env.REACT_APP_REPO_ROOT || '';
}

// Only on-disk docs are editable. rust-course points `file` at a jsdelivr URL,
// not a local path, so those articles get no button.
export function isLocalDocFile(file) {
  return typeof file === 'string' && file.length > 0 && !/^https?:\/\//.test(file);
}

// Where upstream repos are cloned, laid out as <base>/<owner>/<repo>. Defaults
// to the parent of the beatai repo (this machine keeps rust-course at
// <base>/sunface/rust-course); override with REACT_APP_UPSTREAM_BASE if needed.
export function getUpstreamBase() {
  if (process.env.REACT_APP_UPSTREAM_BASE) {
    return process.env.REACT_APP_UPSTREAM_BASE;
  }
  const root = getRepoRoot();
  const i = root.lastIndexOf('/');
  return i > 0 ? root.slice(0, i) : '';
}

// A jsdelivr "gh" URL -> { owner, repo, path }. Upstream-sourced books
// (e.g. rust-course) set `file` to such a URL instead of a local /docs path.
function parseJsdelivrGh(file) {
  const match = /^https?:\/\/cdn\.jsdelivr\.net\/gh\/([^/]+)\/([^/@]+)@[^/]+\/(.+)$/.exec(file || '');
  return match ? { owner: match[1], repo: match[2], path: match[3] } : null;
}

// Absolute on-disk path VSCode should open for an article's `file`:
//   local doc   "/docs/x.md"                     -> <repoRoot>/public/docs/x.md
//   upstream    cdn.jsdelivr.net/gh/o/r@ref/p     -> <upstreamBase>/o/r/p
// Returns '' when unresolvable (no repo root, or an unrecognized URL).
export function resolveEditorPath(file) {
  const root = getRepoRoot();
  if (!root) {
    return '';
  }
  if (isLocalDocFile(file)) {
    const rel = file.startsWith('/') ? file : `/${file}`;
    return `${root}/public${rel}`;
  }
  const gh = parseJsdelivrGh(file);
  const base = getUpstreamBase();
  return gh && base ? `${base}/${gh.owner}/${gh.repo}/${gh.path}` : '';
}

// Whether this article's source can be opened locally (gates the button).
export function canEditFile(file) {
  return resolveEditorPath(file).length > 0;
}

export function buildVscodeUri(file, line = 1, col = 1) {
  const abs = resolveEditorPath(file);
  if (!abs) {
    return '';
  }
  const safeLine = Number.isFinite(line) && line > 0 ? Math.floor(line) : 1;
  const safeCol = Number.isFinite(col) && col > 0 ? Math.floor(col) : 1;
  // encodeURI preserves "/" and ":"; guards against spaces in a repo path.
  return `vscode://file${encodeURI(abs)}:${safeLine}:${safeCol}`;
}

// Strip the inline markdown that react-markdown drops before the renderer
// slugifies a heading, so a raw "## `x` y" line yields the same id the rendered
// heading carries (createMarkdownHeading -> id={slugifyHeading(text)}).
function stripInlineMarkdown(text) {
  return text
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1') // links -> visible text
    .replace(/`([^`]*)`/g, '$1') // inline code
    .replace(/[*_~]{1,3}/g, '') // emphasis / strikethrough markers
    .replace(/<[^>]+>/g, '') // inline html
    .replace(/\s+/g, ' ')
    .trim();
}

// 1-based source line of the heading whose slug === headingId. Mirrors the
// renderer's id scheme and skips fenced code so a "# x" inside a ``` block isn't
// mistaken for a heading. Falls back to line 1 (top of file) when not found.
export function sourceLineForHeadingId(rawDoc, headingId) {
  if (!rawDoc || !headingId) {
    return 1;
  }
  const lines = rawDoc.split('\n');
  let inFence = false;
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    if (/^\s*(```|~~~)/.test(line)) {
      inFence = !inFence;
      continue;
    }
    if (inFence) {
      continue;
    }
    const match = /^(#{1,6})\s+(.+?)\s*#*\s*$/.exec(line);
    if (match && slugifyHeading(stripInlineMarkdown(match[2])) === headingId) {
      return i + 1;
    }
  }
  return 1;
}

function collapseWhitespace(text) {
  return text.replace(/\s+/g, ' ').trim();
}

// First non-empty line of a (possibly multi-line) selection, trimmed and capped
// — i.e. the start of what the reader highlighted.
function selectionSnippet(selectedText) {
  if (!selectedText) {
    return '';
  }
  const first = selectedText
    .split('\n')
    .map((line) => line.trim())
    .find((line) => line.length > 0) || '';
  return first.slice(0, 80);
}

// Locate the reader's selected text in the markdown source. Returns 1-based
// { line, col } of the selection start, or null if not found. Tries an exact
// substring first (precise column), then whitespace-tolerant, then with inline
// markdown stripped (so a selection spanning **bold** / `code` / [links] still
// matches, at column 1).
export function lineColForSelection(rawDoc, selectedText) {
  const snippet = selectionSnippet(selectedText);
  if (!rawDoc || snippet.length < 2) {
    return null;
  }
  const lines = rawDoc.split('\n');

  for (let i = 0; i < lines.length; i += 1) {
    const idx = lines[i].indexOf(snippet);
    if (idx >= 0) {
      return { line: i + 1, col: idx + 1 };
    }
  }

  const target = collapseWhitespace(snippet);
  for (let i = 0; i < lines.length; i += 1) {
    if (collapseWhitespace(lines[i]).includes(target)) {
      return { line: i + 1, col: 1 };
    }
  }
  for (let i = 0; i < lines.length; i += 1) {
    if (collapseWhitespace(stripInlineMarkdown(lines[i])).includes(target)) {
      return { line: i + 1, col: 1 };
    }
  }
  return null;
}
