import { useCallback } from 'react';
import { Pencil } from 'lucide-react';
import {
  buildVscodeUri,
  sourceLineForHeadingId,
  lineColForSelection,
  canEditFile
} from '../../utils/editorLink';
import './DocEditButton.css';

const IS_DEV = process.env.NODE_ENV === 'development';

// The heading whose section the reader is currently in: the last rendered
// heading scrolled above a small top offset, else the first one. Used to open
// VSCode near where the reader is, not just at the top of the file.
function currentHeadingId() {
  if (typeof document === 'undefined') {
    return null;
  }
  const container = document.querySelector('.doc-content');
  if (!container) {
    return null;
  }
  const headings = Array.from(container.querySelectorAll('h1[id], h2[id], h3[id], h4[id]'));
  const OFFSET = 120; // px below viewport top
  let current = null;
  for (let i = 0; i < headings.length; i += 1) {
    if (headings[i].getBoundingClientRect().top - OFFSET <= 1) {
      current = headings[i].id;
    } else {
      break;
    }
  }
  if (!current && headings.length) {
    current = headings[0].id;
  }
  return current;
}

// If the reader has highlighted text inside the article, map that selection to
// its source { line, col }. Returns null when there's no usable in-article
// selection (so the caller falls back to the current-heading line).
function selectionTarget(rawDoc) {
  if (typeof window === 'undefined') {
    return null;
  }
  const selection = window.getSelection();
  if (!selection || selection.isCollapsed || selection.rangeCount === 0) {
    return null;
  }
  const text = selection.toString();
  const container = document.querySelector('.doc-content');
  if (!text.trim() || !container || !container.contains(selection.anchorNode)) {
    return null;
  }
  return lineColForSelection(rawDoc, text);
}

// Dev-only button: opens this page's markdown source in VSCode, positioned at
// the current section's heading line. Hidden in production and for remote
// (rust-course / jsdelivr) articles.
export default function DocEditButton({ file, rawDoc }) {
  const handleClick = useCallback(() => {
    const target = selectionTarget(rawDoc);
    const line = target ? target.line : sourceLineForHeadingId(rawDoc, currentHeadingId());
    const col = target ? target.col : 1;
    const uri = buildVscodeUri(file, line, col);
    if (uri) {
      window.location.href = uri;
    }
  }, [file, rawDoc]);

  if (!IS_DEV || !canEditFile(file)) {
    return null;
  }

  return (
    <button
      type="button"
      className="doc-edit-button"
      onMouseDown={(event) => event.preventDefault()}
      onClick={handleClick}
      title="在 VSCode 中打开此页 Markdown 源文件（选中文字则跳到该处，否则跳到当前章节）"
    >
      <Pencil size={13} aria-hidden="true" />
      Edit
    </button>
  );
}
